<?php include("../inc/header.php"); ?><?include_once $_SERVER['DOCUMENT_ROOT'] . "/module/member/member.lib.php";@session_start();include $_SERVER['DOCUMENT_ROOT'] . "/_api/_NICE/niceapi_token_inc.php";$_SESSION["SEAR_TYPE"] = "social_join";if($_SESSION['social']['id'] == ""){	jsGo("/","","세션이 만료되었습니다. 다시시도해주세요.");	exit();}else{	$userName	= $_SESSION['social']['name'];	$userEmail	= $_SESSION['social']['email'];	$userPhone = str_replace('+82 ', '0', $_SESSION['social']['mobile']);}?><script type="text/javascript">    <!--    function fnNicePopup(){        fnPopup();	// 리얼    }    //--></script><script src="//t1.daumcdn.net/mapjsapi/bundle/postcode/prod/postcode.v2.js"></script><script>    // 우편번호 찾기 화면을 넣을 element    function closeDaumPostcode() {        var element_layer = document.getElementById('layer');        // iframe을 넣은 element를 안보이게 한다.        element_layer.style.display = 'none';    }    function execDaumPostcode(zip_id,address_id,address_ext_id) {        var element_layer = document.getElementById('layer');        new daum.Postcode({            oncomplete: function(data) {                var element_layer = document.getElementById('layer');                // 검색결과 항목을 클릭했을때 실행할 코드를 작성하는 부분.                // 각 주소의 노출 규칙에 따라 주소를 조합한다.                // 내려오는 변수가 값이 없는 경우엔 공백('')값을 가지므로, 이를 참고하여 분기 한다.                var addr = ''; // 주소 변수                var extraAddr = ''; // 참고항목 변수                //사용자가 선택한 주소 타입에 따라 해당 주소 값을 가져온다.                if (data.userSelectedType === 'R') { // 사용자가 도로명 주소를 선택했을 경우                    addr = data.roadAddress;                } else { // 사용자가 지번 주소를 선택했을 경우(J)                    addr = data.jibunAddress;                }                // 사용자가 선택한 주소가 도로명 타입일때 참고항목을 조합한다.                if(data.userSelectedType === 'R'){                    // 법정동명이 있을 경우 추가한다. (법정리는 제외)                    // 법정동의 경우 마지막 문자가 "동/로/가"로 끝난다.                    if(data.bname !== '' && /[동|로|가]$/g.test(data.bname)){                        extraAddr += data.bname;                    }                    // 건물명이 있고, 공동주택일 경우 추가한다.                    if(data.buildingName !== '' && data.apartment === 'Y'){                        extraAddr += (extraAddr !== '' ? ', ' + data.buildingName : data.buildingName);                    }                    // 표시할 참고항목이 있을 경우, 괄호까지 추가한 최종 문자열을 만든다.                    if(extraAddr !== ''){                        extraAddr = ' (' + extraAddr + ')';                    }                    // 조합된 참고항목을 해당 필드에 넣는다.                    addr += extraAddr;                }                // 우편번호와 주소 정보를 해당 필드에 넣는다.                //document.getElementById(zip_id).value = data.zonecode;                document.getElementById(address_id).value = addr;                // 커서를 상세주소 필드로 이동한다.                document.getElementById(address_ext_id).focus();                // iframe을 넣은 element를 안보이게 한다.                // (autoClose:false 기능을 이용한다면, 아래 코드를 제거해야 화면에서 사라지지 않는다.)                element_layer.style.display = 'none';            },            width : '100%',            height : '100%',            maxSuggestItems : 5        }).embed(element_layer);        // iframe을 넣은 element를 보이게 한다.        element_layer.style.display = 'block';        // iframe을 넣은 element의 위치를 화면의 가운데로 이동시킨다.        initLayerPosition();    }    // 브라우저의 크기 변경에 따라 레이어를 가운데로 이동시키고자 하실때에는    // resize이벤트나, orientationchange이벤트를 이용하여 값이 변경될때마다 아래 함수를 실행 시켜 주시거나,    // 직접 element_layer의 top,left값을 수정해 주시면 됩니다.    function initLayerPosition(){        var element_layer = document.getElementById('layer');        var width = 500; //우편번호서비스가 들어갈 element의 width        var height = 400; //우편번호서비스가 들어갈 element의 height        var borderWidth = 5; //샘플에서 사용하는 border의 두께        // 위에서 선언한 값들을 실제 element에 넣는다.        element_layer.style.width = width + 'px';        element_layer.style.height = height + 'px';        element_layer.style.border = borderWidth + 'px solid';        // 실행되는 순간의 화면 너비와 높이 값을 가져와서 중앙에 뜰 수 있도록 위치를 계산한다.        element_layer.style.left = (((window.innerWidth || document.documentElement.clientWidth) - width)/2 - borderWidth) + 'px';        element_layer.style.top = (((window.innerHeight || document.documentElement.clientHeight) - height)/2 - borderWidth) + 'px';    }</script><script language="javascript">    var pw_checker = 0;    //아이디 중복체크    function check_id(uid){        if(uid.length<4){            alert("아이디는 4자 이상 입력해 주세요.");            document.memberForm.user_id.focus();            return ;        }        if(!fnEmailcheck(uid)){            document.memberForm.user_id.focus();            return;        }        if(uid==""){            alert('아이디를 입력하신후 클릭해 주세요.');            document.memberForm.user_id.focus();        } else {            $.get("/module/member/ajax_check_id.php", {user_id: uid},                function(data){                    if(data==0){                        alert('사용 가능한 아이디입니다.');                        document.memberForm.dupcheck.value = uid;                    }else if(data==1){                        alert('이미 사용 중인 아이디입니다. 다른 아이디를 입력해주세요.');                    }else{                        alert('오류가 발생하였습니다. 다시 시도해 주세요.');                    }                    document.memberForm.user_id.focus();                });        }    }    function check_email(uid){        if(uid==""){            alert('이메일을 입력하신후 클릭해 주세요.');            document.memberForm.email.focus();        } else {            $.get("/module/member/ajax_check_email.php", {user_email: uid},                function(data){                    if(data=="0"){                        alert('사용가능한 이메일주소 입니다.');                        document.memberForm.emailcheck.value = uid;                    }else if(data=="1"){                        alert('이미 사용중인 이메일주소 입니다.');                    }else{                        alert('오류가 발생하였습니다. 다시 시도해 주세요.');                    }                    document.memberForm.email.focus();                });        }    }    function check_nick(uid){        if(uid==""){            alert('닉네임을 입력하신후 클릭해 주세요.');            document.memberForm.nick_name.focus();        } else {            $.get("/module/member/ajax_check_nick.php", {nick_name: uid},                function(data){                    if(data=="0"){                        alert('사용가능한 닉네임 입니다.');                        document.memberForm.nickcheck.value = uid;                    }else if(data=="1"){                        alert('이미 사용중인 닉네임 입니다.');                    }else{                        alert('오류가 발생하였습니다. 다시 시도해 주세요.');                    }                    document.memberForm.nick_name.focus();                });        }    }    function info_nick(uid){        if(uid.length < 10){            alert('사업자등록번호를 입력하신 후 클릭해 주세요.');            document.memberForm.etc_2.focus();        } else {            $.get("/module/member/ajax_check_info.php", {info_value: uid},                function(data){                    if(data=="0"){                        alert('사용가능한 사업자등록번호 입니다.');                        document.memberForm.infocheck.value = uid;                    }else if(data=="1"){                        alert('이미 사용중인 사업자등록번호 입니다.');                    }else{                        alert('오류가 발생하였습니다. 다시 시도해 주세요.');                    }                    document.memberForm.etc_2.focus();                });        }    }    function frmCheck(frm){        if (frm.user_id.value.length < 4){            alert("아이디는 4자 이상 입력해 주세요.");            frm.user_id.focus();            return ;        }        if (frm.user_id.value != frm.dupcheck.value){            alert("아이디 중복확인을 해주세요.");            return ;        }        if(!frm.gender.value){ //성별            alert('성별을 선택해 주세요.');            return ;        }        /*if (!fnEmailcheck(frm.user_id.value)){            frm.user_id.focus();            return ;        }*/        // if(pw_checker == 0){        //     alert('비밀번호 형식을 확인을 해주세요');        //     frm.user_pw.focus();        //     return ;        // }        // if(frm.user_pw.value != frm.user_pw1.value){        //     alert('비밀번호가 다릅니다.');        //     frm.user_pw1.focus();        //     return ;        // }        if(frm.user_name.value.length < 1){ //이름            alert('이름을 입력해 주세요.');            frm.user_name.focus();            return ;        }        if(frm.mobile.value.length < 1){	// 휴대폰 번호            alert('연락처를 입력해 주세요.');            frm.mobile.focus();            return ;        }        if (frm.address.value.length < 2){            alert("주소를 입력해 주세요.");            frm.address.focus();            return false;        }        if (frm.address_ext.value.length < 2) {            alert("상세주소를 입력해 주세요.");            frm.address_ext.focus();            return false;        }        /*if(frm.email.value.length < 1){		//            alert('이메일을 입력해 주세요.');            frm.email.focus();            return ;        }        if(!fnEmailcheck(frm.email.value)){            frm.email.focus();            return ;        }        var agree1 = $("#agree01").is(':checked');        if(!agree1){            alert('이용약관에 동의 후 진행이 가능합니다.');            return;        }        var agree2 = $("#agree02").is(':checked');        if(!agree2){            alert('개인정보 수집동의에 동의 후 진행이 가능합니다.');            return;        }*/        frm.submit();    }    function fnEmailcheck(email){        /*===이메일 유호성 검사===*/        var re = /^(([^<>()[\]\\.,;:\s@\"]+(\.[^<>()[\]\\.,;:\s@\"]+)*)|(\".+\"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;        if (email == '' || !re.test(email)) {            alert("올바른 이메일 주소를 입력하세요")            return false;        }else{            return true;        }    }    $(document).ready(function(){        // 숫자만 입력        $(".numberOnly").on("keyup", function() {            $(this).val($(this).val().replace(/[^0-9]/g,""));        });        // 숫자,- 만 입력        $(".phoneOnly").on("keyup", function() {            $(this).val($(this).val().replace(/[^0-9\-]/g,""));        });        // 영문,숫자,특수문자만 입력        $(".pwdCheck").on("keyup", function() {            $(this).val($(this).val().replace(/[^0-9a-zA-Z._@\-]/g,""));        });        // 영문만 입력        $(".engOnly").on("keyup", function() {            $(this).val($(this).val().replace(/[^0-9a-zA-Z._@\-]/g,""));        });        // 영문 띄어쓰기 만 입력        $(".engName").on("keyup", function() {            $(this).val($(this).val().replace(/[^a-zA-Z0-9\s]/gi,""));            $(this).val($(this).val().toUpperCase());        });        // 한글만 입력        $(".hanOnly").on("keyup", function() {            $(this).val($(this).val().replace(/[0-9a-zA-Z!@#$%^&*()_+|\-]/g,""));        });        // 비밀번호 형식        $('#user_pw').change(function(){            //	if(/^(?=.*[a-zA-Z])((?=.*\d))((?=.*\W)).{5,19}$/.exec($(this).val())){		//            if(/^(?!((?:[A-Za-z]+)|(?:[~!@#$%^&*()_+=]+)|(?:[0-9]+))$)[A-Za-z\d~!@#$%^&*()_+=]{8,16}$/.exec($(this).val())){	// 영문/숫자/특수문자 조합 두가지 이상                pw_checker = 1;            }else{                pw_checker = 0;            }        });        // 이용약관 동의        $("#allAgree").click(function(){            if($(this).is(':checked')){                $("#agree01").prop('checked',true);                $("#agree02").prop('checked',true);            }else{                $("#agree01").prop('checked',false);                $("#agree02").prop('checked',false);            }        });    });</script><!-- Container --><div class="container sub" id="container">	<!-- pageTitle -->	<div class="pageTitle inner only mb60">회원가입</div>	<!-- //pageTitle -->	<div class="joinStep">		<div class="box">			<div class="ico no1"></div>			<div class="text">약관동의 및 <br class="mob" />본인인증</div>		</div>		<div class="box">			<div class="ico no2 active"></div>			<div class="text">가입정보입력</div>		</div>		<div class="box">			<div class="ico no3"></div>			<div class="text">가입완료</div>		</div>	</div>	<!-- memberWrap -->	<form name="memberForm" method="post" action="/module/member/member_evn.php" ENCTYPE="multipart/form-data">        <input type="hidden" name="evnMode" value="social_join" />        <input type="hidden" id="dupcheck" name="dupcheck">        <input type="hidden" id="emailcheck" name="emailcheck">        <input type="hidden" id="nickcheck" name="nickcheck">        <input type="hidden" name="member_level" value="1" />        <input type="hidden" name="returnUrl" value="/member/complete.php" />        <input type="hidden" name="join_type" value="<?=$_SESSION['social']['type']?>">        <input type="hidden" name="nick_name" id="nickname" value="<?=$nickName?>">        <input type="hidden" name="email" id="email" value="<?=$userEmail?>">		<div class="memberWrap">			<div class="shadowDiv">				<div class="joinWrap">					<div class="title">						<div class="tit">가입정보입력</div>						<div class="eq"><span>*</span> 는 필수 입력 사항입니다.</div>					</div>					<div class="formJoin">						<div class="line">							<div class="tit">이름<span>*</span></div>							<div class="baseInput">								<input type="text" name="user_name" id="user_name"  value="<?=$userName?>" readonly>							</div>						</div>                        <div class="line">                            <div class="tit">성별<span>*</span></div>                            <div class="baseInput flex_half">                                <div class="baseRadio"><input type="radio" name="gender" id="gnd1" value="M"><label for="gnd1">남</label></div>                                <div class="baseRadio"><input type="radio" name="gender" id="gnd2" value="F"><label for="gnd2">여</label></div>                            </div>                        </div>                        <div class="line">                            <div class="tit">연락처<span>*</span></div>                            <div class="btnInput">                                <div class="baseInput">                                    <input type="text" name="mobile" id="mobile" readonly>                                </div>                                <a href="javascript:fnNicePopup();" class="btn">본인인증</a>                            </div>                        </div>						<div class="line">							<div class="tit">이메일<span>*</span></div>							<div class="btnInput">								<div class="baseInput">									<input type="text" name="user_id" id="user_id" value="<?=$userEmail?>">								</div>								<a href="javascript:check_id(document.memberForm.user_id.value);" class="btn">중복확인</a>							</div>						</div><!--						<div class="line">--><!--							<div class="tit">비밀번호<span>*</span></div>--><!--							<div class="baseInput">--><!--								<input type="password" name="user_pw" id="user_pw" maxlength="12" placeholder="8~12자의 영문 대소문자, 숫자, 특수문자 조합">--><!--							</div>--><!--						</div>--><!--						<div class="line">--><!--							<div class="tit">비밀번호 확인<span>*</span></div>--><!--							<div class="baseInput">--><!--								<input type="password" name="user_pw1" maxlength="12" placeholder="비밀번호를  다시 입력해주세요.">--><!--							</div>--><!--						</div>-->						<div class="line">							<div class="tit">주소<span>*</span></div>							<div class="btnInput">								<div class="baseInput">									<input type="text" name="address" id="address" readonly>								</div>								<a href="javascript:execDaumPostcode('zip','address','address_ext');" class="btn">주소검색</a>							</div>							<div class="baseInput">								<input type="text" name="address_ext" id="address_ext">							</div>						</div>						<div class="line mb1">							<div class="tit">가입경로<span>*</span></div>